def beams(grid):
    """Beams fall from the 2-cell; a beam moves down through 0s, or spreads left/right when blocked by an 8; every visited 0-cell becomes 2."""
    h,w=len(grid),len(grid[0])
    seeds=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
    out=[row[:] for row in grid]
    active=set(seeds)
    for _ in range(h*w+10):
        nxt=set()
        for r,c in active:
            out[r][c]=2
            if r+1<h and grid[r+1][c]==0:
                nxt.add((r+1,c))
            else:
                for dc in(-1,1):
                    cc=c+dc
                    if 0<=cc<w and grid[r][cc]==0:
                        nxt.add((r,cc))
        if nxt==active: break
        active=nxt
    return out

